(function mergePatternsMega() {
  if (typeof PATTERNS === "undefined" || !Array.isArray(PATTERNS.bank)) return;
  const seen = new Set(PATTERNS.bank.map((p) => p.frame + "||" + p.eg));
  PATTERNS_MEGA.forEach((p) => {
    const key = p.frame + "||" + p.eg;
    if (seen.has(key)) return;
    seen.add(key);
    PATTERNS.bank.push(p);
  });
  // Deduplicate in place if base packs had duplicates
  const clean = [];
  const u = new Set();
  PATTERNS.bank.forEach((p) => {
    const key = p.frame + "||" + p.eg;
    if (u.has(key)) return;
    u.add(key);
    clean.push(p);
  });
  PATTERNS.bank = clean;
})();
